python3 -c "
import json
for f in ['accuracy_eval_ds_dense_n50.json', 'accuracy_eval_ds_s015.json', 'accuracy_eval_ds_s030.json']:
    path = f'/root/autodl-tmp/pacs/analysis_output/{f}'
    try:
        d = json.load(open(path))
        results = d.get('results', d) if isinstance(d, dict) else d
        if isinstance(results, list):
            has_snippet = sum(1 for r in results if r.get('gen_snippet'))
            keys = list(results[0].keys()) if results else []
            print(f'{f}: {len(results)} items, {has_snippet} with gen_snippet, keys={keys}')
            if results and 'gen_snippet' in results[0]:
                print(f'  Sample snippet: {results[0][\"gen_snippet\"][:200]}')
            if 'sparsity' in (results[0] if results else {}):
                sparsities = set(r.get('sparsity') for r in results)
                print(f'  Sparsity values: {sparsities}')
            if 'model_type' in (results[0] if results else {}):
                types = set(r.get('model_type') for r in results)
                print(f'  Model types: {types}')
        elif isinstance(results, dict):
            print(f'{f}: dict keys={list(results.keys())[:10]}')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"
